function renderFactories() {
  setHeader('互联工厂','工厂仅能访问自身订单和被要求提交的资料'); const grouped=Object.values(orders.reduce((all,order)=>((all[order.factory_name]||=[]).push(order),all),{}));
  $('#content').innerHTML=`<div class="page"><div class="page-title"><div><h1>互联工厂</h1><p>基于订单自动汇总的协作状态</p></div></div><section class="factory-grid">${grouped.map(group=>{const name=group[0].factory_name;const risks=riskData().filter(item=>item.order.factory_name===name).length;return `<article class="panel factory-card"><div class="factory-mark">${esc(name.slice(0,1))}</div><h2>${esc(name)}</h2><p>进行中 ${group.filter(item=>Number(item.progress)<100).length} 单</p><dl><div><dt>订单总数</dt><dd>${group.length}</dd></div><div><dt>已归档文件</dt><dd>${files.filter(file=>group.some(order=>order.id===file.order_id)).length}</dd></div><div><dt>风险事项</dt><dd class="${risks?'danger':''}">${risks}</dd></div></dl><button class="outline" onclick="showFactoryOrders('${esc(name)}')">查看订单</button></article>`}).join('')||'<p class="empty">订单保存后将自动生成工厂协作卡片。</p>'}</section></div>`;
}
function renderRisks() { const risks=riskData(); setHeader('风险看板','聚合文件、审批、交期、价格和合同风险'); $('#content').innerHTML=`<div class="page"><div class="page-title"><div><h1>风险看板</h1><p>优先处理高风险事项，避免影响订单交付</p></div></div><section class="kpis"><article class="kpi"><span>高风险</span><b class="warning">${risks.filter(item=>item.level==='高').length}</b><small>建议当天处理</small></article><article class="kpi"><span>文件与审批</span><b>${risks.filter(item=>['文件缺失','审批待处理'].includes(item.type)).length}</b><small>合规交付</small></article><article class="kpi"><span>交期与合同</span><b>${risks.filter(item=>['交期延误','合同未签'].includes(item.type)).length}</b><small>履约风险</small></article><article class="kpi"><span>价格未确认</span><b>${risks.filter(item=>item.type==='价格未确认').length}</b><small>成本风险</small></article></section><section class="panel"><div class="table-wrap"><table><thead><tr><th>级别</th><th>风险类型</th><th>订单</th><th>工厂</th><th>说明</th><th></th></tr></thead><tbody>${risks.map(item=>`<tr class="${item.level==='高'?'row-risk':''}"><td>${badge(item.level==='高'?'高风险':'中风险')}</td><td>${esc(item.type)}</td><td>${esc(item.order.product_name)}</td><td>${esc(item.order.factory_name)}</td><td>${esc(item.detail)}</td><td><button class="text-action" onclick="openDetail(${item.order.id})">处理</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">暂无风险事项。</td></tr>'}</tbody></table></div></section></div>`; }
const quoteState = { products: [], factories: [], search: { products:'', factories:'' } };
const quoteColors = ['#176b4a','#267485','#a75b20','#7553a6','#b13f56','#59726b'];
const quoteMoney = item => `${item.currency || 'CNY'} ${Number(item.unit_price || 0).toFixed(2)}`;
const uniqueSorted = values => [...new Set(values.filter(Boolean))].sort((a,b) => a.localeCompare(b, 'zh-CN'));
const quoteData = () => quotes.filter(item => (!quoteState.products.length || quoteState.products.includes(item.product_name)) && (!quoteState.factories.length || quoteState.factories.includes(item.factory_name)));
const quoteOptionValues = type => {
  const source = type === 'product' ? [...quotes.map(item=>item.product_name),...orders.map(item=>item.product_name)] : [...quotes.map(item=>item.factory_name),...orders.map(item=>item.factory_name)];
  return uniqueSorted([...source,...quoteOptions.filter(item=>item.option_type===type).map(item=>item.value)]);
};
function multiPicker(id, type, selected) {
  const title=t(type), search=quoteState.search[`${type}s`] || '', values=quoteOptionValues(type), customByValue=new Map(quoteOptions.filter(item=>item.option_type===type).map(item=>[item.value,item]));
  const filtered=values.filter(value=>value.toLowerCase().includes(search.toLowerCase()));
  const selectAll = language==='en' ? 'Select all' : language==='ko' ? '모두 선택' : '一键全选';
  return `<details class="multi-picker" id="${id}"><summary>${selected.length ? selected.map(esc).join('、') : title}</summary><div class="picker-menu"><div class="picker-tools"><input type="search" data-picker-search="${type}s" placeholder="${t('search')}" value="${esc(search)}"><span class="picker-actions"><button type="button" class="text-action clear-picker" data-picker="${id}">${t('clear')}</button><button type="button" class="text-action select-all-picker" data-picker="${id}">${selectAll}</button></span></div><div class="picker-options">${filtered.map(value=>{const custom=customByValue.get(value);return `<div class="picker-option"><label><input type="checkbox" value="${esc(value)}" ${selected.includes(value)?'checked':''}><b>${esc(value)}</b></label>${custom&&user.role==='brand'?`<span><button type="button" class="option-icon" title="${t('edit')}" onclick="editQuoteOption(${custom.id},'${esc(value)}','${type}')">✎</button><button type="button" class="option-icon danger" title="${t('delete')}" onclick="deleteQuoteOption(${custom.id})">×</button></span>`:''}</div>`;}).join('') || `<small class="picker-empty">${t('noOptions')}</small>`}</div>${user.role==='brand'?`<button type="button" class="text-action add-picker-item" data-type="${type}">+ ${t('add')}${title}</button>`:''}</div></details>`;
}
function trendChart(data) {
  if (!data.length) return `<div class="empty chart-empty">${t('noChart')}</div>`;
  const byProduct = Object.entries(data.reduce((all,item) => ((all[item.product_name] ||= []).push(item),all),{}));
  const allPrices = data.map(item => Number(item.unit_price)); const min = Math.min(...allPrices), max = Math.max(...allPrices); const pad = Math.max((max - min) * .1, max * .03, 1); const yMin = Math.max(0, min-pad), yMax=max+pad, span=yMax-yMin || 1;
  const dates = uniqueSorted(data.map(item=>String(item.quoted_at).slice(0,10))).sort(); const x = date => 13 + (dates.indexOf(String(date).slice(0,10)) / Math.max(1, dates.length-1)) * 82; const y = price => 82 - ((Number(price)-yMin)/span)*66;
  const grid = Array.from({length:5},(_,i)=>{const value=yMin+(span*i/4), py=y(value);return `<g><line x1="13" y1="${py}" x2="95" y2="${py}" class="chart-grid"/><text x="11" y="${py+2}" text-anchor="end">${value.toFixed(2)}</text></g>`;}).join('');
  const lines = byProduct.map(([product,items],index)=>{const color=quoteColors[index%quoteColors.length], ordered=items.slice().sort((a,b)=>new Date(a.quoted_at)-new Date(b.quoted_at)); const points=ordered.map(item=>`${x(item.quoted_at)},${y(item.unit_price)}`).join(' ');return `<g><polyline points="${points}" fill="none" stroke="${color}" stroke-width=".8" vector-effect="non-scaling-stroke"/>${ordered.map(item=>`<circle cx="${x(item.quoted_at)}" cy="${y(item.unit_price)}" r="1.3" fill="${color}"><title>${esc(`${fmtDay(item.quoted_at)} | ${item.factory_name} | ${quoteMoney(item)} | MOQ ${item.moq || '-'}`)}</title></circle><text class="point-label" x="${x(item.quoted_at)}" y="${y(item.unit_price)-3}">${Number(item.unit_price).toFixed(2)}</text>`).join('')}</g>`;}).join('');
  return `<div class="trend-wrap"><svg class="quote-chart quote-trend" viewBox="0 0 100 100" role="img" aria-label="${t('trend')}">${grid}<line x1="13" y1="82" x2="95" y2="82" class="chart-axis"/><line x1="13" y1="16" x2="13" y2="82" class="chart-axis"/>${lines}${dates.map((date,i)=>`<text x="${13+(i/Math.max(1,dates.length-1))*82}" y="91" text-anchor="middle">${date.slice(5)}</text>`).join('')}<text x="54" y="99" text-anchor="middle">${t('priceDate')}</text><text x="3" y="50" transform="rotate(-90 3 50)" text-anchor="middle">${t('priceCny')}</text></svg><div class="chart-legend">${byProduct.map(([product],i)=>`<span><i style="background:${quoteColors[i%quoteColors.length]}"></i>${esc(product)}</span>`).join('')}</div></div>`;
}
function comparisonChart(data) {
  const groups = Object.entries(data.reduce((all,item) => ((all[item.product_name] ||= []).push(item),all),{}));
  if (!groups.length) return `<p class="empty">${t('noChart')}</p>`;
  return groups.map(([product,items])=>{const latest=Object.values(items.reduce((all,item)=>{const old=all[item.factory_name];if(!old||new Date(old.quoted_at)<=new Date(item.quoted_at))all[item.factory_name]=item;return all;},{}));const low=Math.min(...latest.map(item=>Number(item.unit_price))),high=Math.max(...latest.map(item=>Number(item.unit_price))),max=Math.max(high,1),lowItem=latest.find(item=>Number(item.unit_price)===low);const delta=high-low;return `<div class="comparison-group"><div class="comparison-summary"><b>${esc(product)}</b><span>${t('latest')} ${esc(lowItem.factory_name)} ${quoteMoney(lowItem)}，${t('spread')} ${lowItem.currency || 'CNY'} ${delta.toFixed(2)}（${low ? `+${(delta/low*100).toFixed(1)}` : '0.0'}%）</span></div><div class="vertical-bars">${latest.map(item=>{const price=Number(item.unit_price),kind=price===low?'lowest':price===high&&high!==low?'highest':'normal';return `<div class="bar-item ${kind}"><b>${quoteMoney(item)}</b><i style="height:${Math.max(10,price/max*145)}px"></i><span>${esc(item.factory_name)}</span></div>`;}).join('')}</div></div>`;}).join('');
}
function bindQuotePicker(id, key) { const picker=$(`#${id}`);picker.ontoggle=()=>{if(picker.open)document.querySelectorAll('.multi-picker[open]').forEach(item=>{if(item!==picker)item.open=false;});};picker.querySelectorAll('input[type="checkbox"]').forEach(input=>input.onchange=()=>{quoteState[key]=[...picker.querySelectorAll('input:checked')].map(item=>item.value);renderQuotes();});picker.querySelectorAll('[data-picker-search]').forEach(input=>input.oninput=()=>{quoteState.search[input.dataset.pickerSearch]=input.value;renderQuotes();});picker.querySelectorAll('.clear-picker').forEach(button=>button.onclick=()=>{quoteState[key]=[];renderQuotes();});picker.querySelectorAll('.select-all-picker').forEach(button=>button.onclick=()=>{quoteState[key]=quoteOptionValues(key==='products'?'product':'factory');renderQuotes();});picker.querySelectorAll('.add-picker-item').forEach(button=>button.onclick=()=>openQuoteOptionForm(button.dataset.type)); }
function renderQuotes() {
  const products=quoteOptionValues('product'), factories=quoteOptionValues('factory'); quoteState.products=quoteState.products.filter(item=>products.includes(item));quoteState.factories=quoteState.factories.filter(item=>factories.includes(item)); const validProduct=quoteState.products.length>0; const data=(validProduct?quoteData():[]).sort((a,b)=>new Date(a.quoted_at)-new Date(b.quoted_at));
  setHeader(t('quoteTitle'),t('quoteSub')); $('#content').innerHTML=`<div class="page"><div class="page-title"><div><h1>${t('quoteTitle')}</h1><p>${t('quoteSub')}</p></div>${user.role==='brand'?`<button class="primary" onclick="openQuoteForm()">${t('quoteEntry')}</button>`:''}</div><div class="filters quote-filters">${multiPicker('quoteProducts','product',quoteState.products)}${multiPicker('quoteFactories','factory',quoteState.factories)}<small class="filter-hint">${validProduct ? t('allFactories') : `${t('product')} *`}</small><button type="button" class="outline" onclick="openQuoteSources()">${t('history')}</button>${user.role==='brand'?`<button type="button" class="outline" onclick="openQuoteImport()">${t('import')}</button>`:''}</div><div id="quoteBoard"><div class="quote-grid"><section class="panel"><div class="panel-head"><div><h2>${t('trend')}</h2><p>${t('trendSub')}</p></div></div>${trendChart(data)}</section><section class="panel"><div class="panel-head"><div><h2>${t('comparison')}</h2><p>${t('comparisonSub')}</p></div></div><div class="quote-comparison">${comparisonChart(data)}</div></section></div><section class="panel"><div class="panel-head"><div><h2>${t('details')}</h2><p>${t('detailsSub')}</p></div></div><div class="table-wrap"><table><thead><tr><th>${t('date')}</th><th>${t('productName')}</th><th>${t('factory')}</th><th>${t('unitPrice')}</th><th>${t('moq')}</th><th>${t('sampleFee')}</th><th>${t('cycle')}</th><th>${t('payment')}</th><th>${t('note')}</th><th>${t('source')}</th><th></th></tr></thead><tbody>${data.slice().reverse().map(item=>`<tr><td>${fmtDay(item.quoted_at)}</td><td>${esc(item.product_name)}</td><td>${esc(item.factory_name)}</td><td><b>${quoteMoney(item)}</b></td><td>${esc(item.moq||'-')}</td><td>${esc(item.sample_fee||'-')}</td><td>${esc(item.production_days||'-')}</td><td>${esc(item.payment_terms||'-')}</td><td>${esc(item.note||'-')}</td><td>${esc(item.source_file_name||t('legacy'))}</td><td>${user.role==='brand'?`<button class="text-action" onclick="openQuoteEdit(${item.id})">${t('edit')}</button>`:''}</td></tr>`).join('')||`<tr><td colspan="11" class="empty">${validProduct?t('noQuote'):`${t('product')} *`}</td></tr>`}</tbody></table></div></section></div></div>`;
  bindQuotePicker('quoteProducts','products');bindQuotePicker('quoteFactories','factories');
}
function render() { activateNav(); ({dashboard:renderDashboard,orders:renderOrders,documents:renderDocuments,factories:renderFactories,quotes:renderQuotes,risks:renderRisks})[view](); }
window.showView = value => { view=value; render(); };
window.showFactoryOrders = factory => { view='orders'; render(); $('#factoryFilter').value=factory; $('#factoryFilter').dispatchEvent(new Event('input')); };
function orderForm(order={}) { return `<div class="modal-head"><div><h2>${order.id?'编辑代工订单':'新建代工订单'}</h2><p>先建立产品与工厂，再通过里程碑推进生产。</p></div><button type="button" class="icon-close" onclick="orderModal.close()">×</button></div><div class="form-grid"><label>产品名称 *<input name="product_name" required value="${esc(order.product_name||'')}"></label><label>工厂名称 *<input name="factory_name" required value="${esc(order.factory_name||'')}"></label><label>产品 SKU<input name="sku" value="${esc(order.sku||'')}" placeholder="确认配方和工厂后更新"></label><label>约定交期<input type="date" name="due_date" value="${esc(order.due_date||'')}"></label><label>生产数量<input name="quantity" value="${esc(order.quantity||'')}"></label><label>保质期要求（月）<input type="number" min="1" name="shelf_life" value="${esc(order.shelf_life||'')}"></label><label>批号<input name="batch_no" value="${esc(order.batch_no||'')}"></label><label>订单状态<input name="status" value="${esc(order.status||'待确认')}"></label><label>配方版本<input name="formula_version" value="${esc(order.formula_version||'')}"></label><label>包装规格<input name="pack_spec" value="${esc(order.pack_spec||'')}"></label><label>合同号（上传合同后补充）<input name="contract_no" value="${esc(order.contract_no||'')}"></label><label class="wide">完整配方<textarea name="formula">${esc(order.formula||'')}</textarea></label></div><footer><button type="button" class="secondary" onclick="orderModal.close()">取消</button><button class="primary">保存订单</button></footer>`; }
window.openOrderForm=()=>{editing=null;$('#orderForm').innerHTML=orderForm();$('#orderModal').showModal();}; window.editOrder=id=>{editing=orderById(id);$('#orderForm').innerHTML=orderForm(editing);$('#orderModal').showModal();};
$('#orderForm').onsubmit=async event=>{event.preventDefault();const data=Object.fromEntries(new FormData(event.target));try{await api(editing?`/api/orders/${editing.id}`:'/api/orders',{method:editing?'PUT':'POST',body:JSON.stringify(data)});$('#orderModal').close();await loadData();render();}catch(error){alert(error.message);}};
function milestoneRows(order) { return (order.milestones||[]).map(item=>`<tr class="${overdue(item)?'row-risk':''}"><td><b>${esc(item.node_name)}</b></td><td><input class="date-input" type="date" value="${esc(item.plan_date||'')}" ${user.role==='factory'?'disabled':''} onchange="updateMilestone(${order.id},${item.id},'plan_date',this.value)"></td><td><input class="date-input" type="date" value="${esc(item.actual_date||'')}" onchange="updateMilestone(${order.id},${item.id},'actual_date',this.value)"></td><td><select onchange="updateMilestone(${order.id},${item.id},'status',this.value)">${['待开始','进行中','已完成','延期'].map(value=>`<option ${item.status===value?'selected':''}>${value}</option>`).join('')}</select></td><td><input class="reason-input" value="${esc(item.delay_reason||'')}" placeholder="延期时填写原因" onchange="updateMilestone(${order.id},${item.id},'delay_reason',this.value)"></td></tr>`).join(''); }
function reviewActions(file, orderId) { return user.role==='brand'&&file.uploaded_by_role==='factory'&&['待审批','需修改后重提'].includes(file.review_status)?`<button class="text-action approve" onclick="openReview(${file.id},${orderId})">审批</button>`:''; }
function commentsHtml(order) { return `<section class="panel inset comments"><div class="panel-head"><div><h3>对话与决策留痕</h3><p>可记录确认结论、@成员和下一步要求</p></div></div><form id="commentForm" class="comment-form"><textarea name="message" required placeholder="例如：配方 V3 已确认，请于 8 月 20 日前安排打样。"></textarea><input name="mentions" placeholder="@成员或部门（选填）"><button class="primary">发送记录</button></form><ol>${(order.comments||[]).map(item=>`<li><b>${esc(item.created_by_name)}</b><span>${esc(item.message)}</span>${item.mentions?`<small>提及：${esc(item.mentions)}</small>`:''}<small>${fmtDate(item.created_at)}</small></li>`).join('')||'<li class="empty">暂无评论，关键确认请在此记录。</li>'}</ol></section>`; }
window.openDetail=async id=>{const order=await api(`/api/orders/${id}`);const unread=reminders.filter(item=>item.order_id===order.id&&!item.read_at);const rows=order.files.map(file=>`<tr><td><span class="document-name"><b>${esc(file.original_name)}</b>${previewButton(file.id)}</span></td><td>${esc(docTypes[file.document_type]||file.document_type||'其他文件')}</td><td>${esc(file.uploaded_by_name||'系统')}</td><td>${fmtDate(file.created_at)}</td><td>${badge(file.review_status)}</td><td><button class="text-action" onclick="downloadFile(${file.id},'${esc(file.original_name)}')">下载</button>${reviewActions(file,order.id)}${user.role==='brand'||file.uploaded_by_name===user.name?`<button class="text-action danger" onclick="deleteFile(${file.id},${order.id})">删除</button>`:''}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">尚未上传文件。</td></tr>';$('#detailBody').innerHTML=`<div class="modal-head"><div><h2>${esc(order.product_name)}</h2><p>${esc(order.factory_name)}${order.sku?` · SKU ${esc(order.sku)}`:''}</p></div><button class="icon-close" onclick="detailModal.close()">×</button></div><div class="detail-summary"><div><small>当前节点</small><b>${esc(order.node||'待确认')}</b>${progress(order)}</div><div><small>约定交期</small><b>${fmtDay(order.due_date)}</b></div><div><small>保质期要求</small><b>${order.shelf_life?`${esc(order.shelf_life)} 个月`:'待确认'}</b></div><div><small>工厂提醒</small><b>${unread.length?`${unread.length} 条未读`:'暂无未读'}</b>${user.role==='brand'?`<button class="text-action" onclick="sendReminder(${order.id})">一键提醒工厂</button>`:''}</div></div><div class="detail-columns"><section class="panel inset"><div class="panel-head"><h3>产品与配方信息</h3>${user.role==='brand'?`<button class="text-action" onclick="detailModal.close();editOrder(${order.id})">编辑</button>`:''}</div><dl class="facts">${[['产品名称',order.product_name],['工厂名称',order.factory_name],['SKU / 条码',order.sku||'确认配方和工厂后申请'],['合同号',order.contract_no||'合同待上传'],['生产数量',order.quantity],['配方版本',order.formula_version],['包装规格',order.pack_spec],['订单状态',order.status]].map(([label,value])=>`<div><dt>${label}</dt><dd>${esc(value||'待补充')}</dd></div>`).join('')}</dl><div class="formula"><small>完整配方</small><p>${esc(order.formula||'待补充')}</p></div></section><section class="panel inset"><div class="panel-head"><h3>里程碑状态</h3><small>${(order.milestones||[]).filter(overdue).length} 项已逾期</small></div><ol class="timeline">${(order.milestones||[]).map(item=>`<li class="${item.actual_date?'complete':overdue(item)?'late':''}"><i>${item.sequence}</i><div><b>${esc(item.node_name)}</b><small>计划 ${fmtDay(item.plan_date)} · ${item.actual_date?`实际 ${fmtDay(item.actual_date)}`:item.status}${item.delay_reason?` · ${esc(item.delay_reason)}`:''}</small></div></li>`).join('')}</ol></section></div><section class="panel inset milestone-board"><div class="panel-head"><div><h3>里程碑计划与预警</h3><p>计划日期由品牌方维护；实际日期、状态和延期原因双方可更新。</p></div></div><div class="table-wrap"><table><thead><tr><th>节点</th><th>计划日期</th><th>实际日期</th><th>状态</th><th>延期原因</th></tr></thead><tbody>${milestoneRows(order)}</tbody></table></div></section><section class="panel inset documents document-table"><div class="panel-head"><div><h3>订单全部文档</h3><p>选择文件类型后上传；工厂文件需经过审批。</p></div><form id="uploadForm"><select name="document_type" required><option value="" selected disabled>请选择文件类型</option>${Object.entries(docTypes).map(([value,label])=>`<option value="${value}">${label}</option>`).join('')}<option value="custom">+ 手动添加新选项</option></select><input name="custom_document_type" hidden placeholder="自定义文件类型"><input type="file" name="file" required><button class="outline">上传文件</button><button type="button" class="outline" onclick="downloadAllFiles(${order.id})">下载全部</button></form></div><div class="table-wrap"><table><thead><tr><th>文件名称</th><th>文件类型</th><th>上传人</th><th>上传时间</th><th>审批状态</th><th></th></tr></thead><tbody>${rows}</tbody></table></div></section>${commentsHtml(order)}<section class="panel inset action-log"><div class="panel-head"><h3>系统协作记录</h3></div><ol>${order.actions.map(item=>`<li><b>${esc(item.action)}</b><span>${esc(item.detail||'订单协作更新')}</span><small>${esc(item.actor_name)} · ${fmtDate(item.created_at)}</small></li>`).join('')||'<li class="empty">暂未产生协作记录。</li>'}</ol></section>`;$('#detailModal').showModal();const type=$('#uploadForm select');const custom=$('#uploadForm input[name="custom_document_type"]');type.onchange=()=>{custom.hidden=type.value!=='custom';custom.required=type.value==='custom';};$('#uploadForm').onsubmit=async event=>{event.preventDefault();const form=new FormData(event.target);if(form.get('document_type')==='custom')form.set('document_type',form.get('custom_document_type'));try{await api(`/api/orders/${order.id}/files`,{method:'POST',body:form});await loadData();openDetail(order.id);}catch(error){alert(error.message);}};$('#commentForm').onsubmit=async event=>{event.preventDefault();const data=Object.fromEntries(new FormData(event.target));try{await api(`/api/orders/${order.id}/comments`,{method:'POST',body:JSON.stringify(data)});await loadData();openDetail(order.id);}catch(error){alert(error.message);}};};
window.updateMilestone=async(orderId,id,key,value)=>{try{await api(`/api/orders/${orderId}/milestones/${id}`,{method:'PUT',body:JSON.stringify({[key]:value})});await loadData();openDetail(orderId);}catch(error){alert(error.message);}};
window.sendReminder=async orderId=>{const message=prompt('发送给工厂的提醒内容：','请更新当前生产节点、计划日期和待交付资料。');if(!message)return;try{await api(`/api/orders/${orderId}/reminders`,{method:'POST',body:JSON.stringify({message})});await loadData();openDetail(orderId);}catch(error){alert(error.message);}};
const notificationAnchor = item => item?.source_anchor || (String(item?.kind).includes('文件') || String(item?.title).includes('订单全部文档') ? 'documentsSection' : String(item?.kind).includes('里程碑') || String(item?.title).includes('里程碑') ? 'milestoneSection' : String(item?.kind).includes('评论') || String(item?.title).includes('留言') ? 'commentsSection' : 'detailTop');
window.readNotification=async(id,orderId)=>{try{const item=notifications.find(notification=>notification.id===Number(id));await api(`/api/notifications/${id}/read`,{method:'POST'});await loadData();await openDetail(orderId,notificationAnchor(item));}catch(error){alert(error.message);}};
window.openReview=(fileId,orderId)=>{const file=files.find(item=>item.id===Number(fileId));$('#reviewForm').innerHTML=`<div class="modal-head"><div><h2>文件审批</h2><p>${esc(file?.original_name||'')}</p></div><button type="button" class="icon-close" onclick="reviewModal.close()">×</button></div><div class="form-grid"><label>审批结果<select name="decision"><option>确认</option><option>有条件通过</option><option>需修改后重提</option><option>驳回</option><option>转交同事审批</option></select></label><label>标准原因标签<select name="reason_tag"><option value="">请选择（确认可不填）</option>${reasonTags.map(item=>`<option>${item}</option>`).join('')}</select></label><label>修改/处理截止日期<input name="due_date" type="date"></label><label>转交对象<input name="transfer_to" placeholder="同事姓名或邮箱"></label><label class="wide">处理说明<textarea name="note" placeholder="请清楚说明确认条件、需修改内容或驳回原因"></textarea></label></div><footer><button type="button" class="secondary" onclick="reviewModal.close()">取消</button><button class="primary">提交审批</button></footer>`;$('#reviewModal').showModal();$('#reviewForm').onsubmit=async event=>{event.preventDefault();try{await api(`/api/files/${fileId}/review`,{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(event.target)))});$('#reviewModal').close();await loadData();openDetail(orderId);}catch(error){alert(error.message);}};};
window.openQuoteOptionForm=(type,id=null,current='')=>{const label=t(type);$('#quoteForm').innerHTML=`<div class="modal-head"><div><h2>${id?t('optionEdit',{type:label}):t('optionTitle',{type:label})}</h2></div><button type="button" class="icon-close" onclick="quoteModal.close()">×</button></div><div class="form-grid"><label class="wide">${t('optionName')} *<input name="value" required value="${esc(current)}"></label></div><footer><button type="button" class="secondary" onclick="quoteModal.close()">${t('cancel')}</button><button class="primary">${t('save')}</button></footer>`;$('#quoteModal').showModal();$('#quoteForm').onsubmit=async event=>{event.preventDefault();try{const data=Object.fromEntries(new FormData(event.target));await api(id?`/api/quote-filter-options/${id}`:'/api/quote-filter-options',{method:id?'PUT':'POST',body:JSON.stringify(id?data:{...data,option_type:type})});$('#quoteModal').close();await loadData();render();}catch(error){alert(error.message);}};};
window.editQuoteOption=(id,value,type)=>openQuoteOptionForm(type,id,value);
window.deleteQuoteOption=async id=>{if(!confirm(t('confirmDelete')))return;try{await api(`/api/quote-filter-options/${id}`,{method:'DELETE'});await loadData();render();}catch(error){alert(error.message);}};
function quoteFormHtml(item = {}) { const products=quoteOptionValues('product'),factories=quoteOptionValues('factory');return `<div class="modal-head"><div><h2>${item.id?t('editQuote'):t('newQuote')}</h2><p>${t('sync')}</p></div><button type="button" class="icon-close" onclick="quoteModal.close()">×</button></div><div class="form-grid"><label>${t('productName')} *<input name="product_name" required list="quoteProductList" value="${esc(item.product_name||'')}"></label><label>${t('factory')} *<input name="factory_name" required list="factoryList" value="${esc(item.factory_name||'')}"></label><label>${t('unitPrice')} *<input type="number" step="0.0001" min="0" name="unit_price" required value="${esc(item.unit_price??'')}"></label><label>${t('currency')} *<select name="currency">${['CNY','USD','KRW'].map(currency=>`<option ${String(item.currency||'CNY')===currency?'selected':''}>${currency}</option>`).join('')}</select></label><label>${t('date')} *<input type="date" name="quoted_at" value="${esc(item.quoted_at||new Date().toISOString().slice(0,10))}" required></label><label>${t('moq')}<input name="moq" value="${esc(item.moq||'')}"></label><label>${t('sampleFee')}<input name="sample_fee" value="${esc(item.sample_fee||'')}"></label><label>${t('cycle')}<input name="production_days" value="${esc(item.production_days||'')}"></label><label class="wide">${t('payment')}<input name="payment_terms" value="${esc(item.payment_terms||'')}"></label><label class="wide">${t('note')}<textarea name="note">${esc(item.note||'')}</textarea></label></div><datalist id="quoteProductList">${products.map(value=>`<option value="${esc(value)}">`).join('')}</datalist><datalist id="factoryList">${factories.map(value=>`<option value="${esc(value)}">`).join('')}</datalist><footer><button type="button" class="secondary" onclick="quoteModal.close()">${t('cancel')}</button><button class="primary">${t('save')}</button></footer>`; }
window.openQuoteForm=()=>{ $('#quoteForm').innerHTML=quoteFormHtml(); $('#quoteModal').showModal(); $('#quoteForm').onsubmit=async event=>{event.preventDefault();try{await api('/api/quotes',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(event.target)))});$('#quoteModal').close();await loadData();render();}catch(error){alert(error.message);}}; };
window.openQuoteEdit=id=>{const item=quotes.find(quote=>quote.id===Number(id));if(!item)return;$('#quoteForm').innerHTML=quoteFormHtml(item);$('#quoteModal').showModal();$('#quoteForm').onsubmit=async event=>{event.preventDefault();try{await api(`/api/quotes/${id}`,{method:'PUT',body:JSON.stringify(Object.fromEntries(new FormData(event.target)))});$('#quoteModal').close();await loadData();render();}catch(error){alert(error.message);}};};
window.openQuoteImport=()=>{ $('#quoteImportForm').innerHTML=`<div class="modal-head"><div><h2>导入历史源数据</h2><p>Excel 必须含“产品名称、采购成本、工厂名称、谈判时间”；原表将保留以供追溯。</p></div><button type="button" class="icon-close" onclick="quoteImportModal.close()">×</button></div><div class="form-grid"><label class="wide">表格名称 *<input name="display_name" required placeholder="例如：2026 年 8 月成品价格谈判"></label><label class="wide">Excel 报价表 *<input name="file" type="file" accept=".xlsx,.xls" required></label></div><footer><button type="button" class="secondary" onclick="quoteImportModal.close()">取消</button><button class="primary">上传并导入</button></footer>`;$('#quoteImportModal').showModal();$('#quoteImportForm').onsubmit=async event=>{event.preventDefault();try{const result=await api('/api/quote-imports',{method:'POST',body:new FormData(event.target)});alert(`已处理 ${result.imported_count} 条报价${result.updated_count?`，其中 ${result.updated_count} 条已关联既有记录`:''}${result.skipped_rows?`，跳过 ${result.skipped_rows} 行无效数据`:''}。`);$('#quoteImportModal').close();await loadData();render();}catch(error){alert(error.message);}}; };
window.openQuoteSources=async()=>{try{const {imports,legacy_count}=await api('/api/quote-imports');const legacy=legacy_count?`<section class="source-item legacy-source"><div><b>历史录入数据</b><small>已有 ${legacy_count} 条报价记录；该批记录未保存原始 Excel，因此不可预览原表。</small></div></section>`:'';$('#quoteSourcesBody').innerHTML=`<div class="modal-head"><div><h2>历史报价源数据</h2><p>按导入批次追溯原表，并可编辑底层报价记录。</p></div><button class="icon-close" type="button" onclick="quoteSourcesModal.close()">×</button></div><div class="quote-sources-list">${imports.map(source=>`<section class="source-item"><div><b>${esc(source.display_name)}</b><small>${fmtDate(source.uploaded_at)} · ${esc(source.source_file_name||'未上传原表')} · ${source.record_count} 条数据 · 产品：${esc((source.products||[]).join('、')||'-')} · 工厂：${esc((source.factories||[]).join('、')||'-')} · 上传人 ${esc(source.uploaded_by_name)}</small></div><span><button class="text-action" onclick="renameQuoteSource(${source.id},'${esc(source.display_name)}')">改名</button><button class="text-action" onclick="viewQuoteSourceRecords(${source.id},'${esc(source.display_name)}')">查看数据</button>${source.storage_path?`<button class="text-action" onclick="downloadQuoteSource(${source.id},'${esc(source.source_file_name||source.display_name)}')">下载原表</button>`:''}</span></section>`).join('')||'<p class="empty">尚未上传可追溯的历史报价表。</p>'}${legacy}</div><footer><button type="button" class="primary" onclick="quoteSourcesModal.close()">关闭</button></footer>`;$('#quoteSourcesModal').showModal();}catch(error){alert(error.message);}};
window.viewQuoteSourceRecords=(id,name)=>{const records=quotes.filter(item=>Number(item.import_id)===Number(id));$('#quoteSourcesBody').innerHTML=`<div class="modal-head"><div><h2>${esc(name)}</h2><p>原表导入的 ${records.length} 条报价数据，可在报价明细中继续编辑。</p></div><button class="icon-close" type="button" onclick="openQuoteSources()">×</button></div><div class="quote-sources-list"><div class="table-wrap"><table><thead><tr><th>日期</th><th>产品</th><th>工厂</th><th>单价</th><th>MOQ</th><th>备注</th></tr></thead><tbody>${records.map(item=>`<tr><td>${fmtDay(item.quoted_at)}</td><td>${esc(item.product_name)}</td><td>${esc(item.factory_name)}</td><td>${quoteMoney(item)}</td><td>${esc(item.moq||'-')}</td><td>${esc(item.note||'-')}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">该批次数据尚未加载。</td></tr>'}</tbody></table></div></div><footer><button class="secondary" type="button" onclick="openQuoteSources()">返回列表</button><button class="primary" type="button" onclick="quoteSourcesModal.close()">关闭</button></footer>`;};
window.renameQuoteSource=async(id,current)=>{const display_name=prompt('表格名称：',current);if(!display_name?.trim())return;try{await api(`/api/quote-imports/${id}`,{method:'PUT',body:JSON.stringify({display_name})});openQuoteSources();}catch(error){alert(error.message);}};
window.downloadQuoteSource=async(id,name)=>{try{const blob=await getFile(`/api/quote-imports/${id}/file`);const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);}catch(error){alert(error.message);}};
window.openQuoteImport=()=>{ $('#quoteImportForm').innerHTML=`<div class="modal-head"><div><h2>${t('importTitle')}</h2><p>${t('importSub')}</p></div><button type="button" class="icon-close" onclick="quoteImportModal.close()">×</button></div><div class="form-grid"><label class="wide">${t('tableName')} *<input name="display_name" required></label><label class="wide">${t('chooseExcel')} *<input name="file" type="file" accept=".xlsx,.xls" required></label></div><footer><button type="button" class="secondary" onclick="quoteImportModal.close()">${t('cancel')}</button><button class="primary">${t('upload')}</button></footer>`;$('#quoteImportModal').showModal();$('#quoteImportForm').onsubmit=async event=>{event.preventDefault();try{const result=await api('/api/quote-imports',{method:'POST',body:new FormData(event.target)});alert(`${t('optionSaved')} · ${result.imported_count} ${t('records')}`);$('#quoteImportModal').close();await loadData();render();}catch(error){alert(error.message);}};};
window.openQuoteSources=async()=>{try{const {imports,legacy_count}=await api('/api/quote-imports');const legacy=legacy_count?`<section class="source-item legacy-source"><div><b>${t('legacy')}</b><small>${t('legacyInfo',{count:legacy_count})}</small></div></section>`:'';$('#quoteSourcesBody').innerHTML=`<div class="modal-head"><div><h2>${t('historyTitle')}</h2><p>${t('historySub')}</p></div><button class="icon-close" type="button" onclick="quoteSourcesModal.close()">×</button></div><div class="quote-sources-list">${imports.map(source=>`<section class="source-item"><div><b>${esc(source.display_name)}</b><small>${fmtDate(source.uploaded_at)} · ${esc(source.source_file_name||'-')} · ${source.record_count} ${t('records')} · ${t('product')}：${esc((source.products||[]).join('、')||'-')} · ${t('factory')}：${esc((source.factories||[]).join('、')||'-')} · ${t('uploadedBy')} ${esc(source.uploaded_by_name)}</small></div><span><button class="text-action" onclick="renameQuoteSource(${source.id},'${esc(source.display_name)}')">${t('rename')}</button><button class="text-action" onclick="viewQuoteSourceRecords(${source.id},'${esc(source.display_name)}')">${t('viewData')}</button>${source.storage_path?`<button class="text-action" onclick="downloadQuoteSource(${source.id},'${esc(source.source_file_name||source.display_name)}')">${t('download')}</button>`:''}</span></section>`).join('')||`<p class="empty">${t('noSource')}</p>`}${legacy}</div><footer><button type="button" class="primary" onclick="quoteSourcesModal.close()">${t('close')}</button></footer>`;$('#quoteSourcesModal').showModal();}catch(error){alert(error.message);}};
window.viewQuoteSourceRecords=(id,name)=>{const records=quotes.filter(item=>Number(item.import_id)===Number(id));$('#quoteSourcesBody').innerHTML=`<div class="modal-head"><div><h2>${esc(name)}</h2><p>${t('sourceRecords',{count:records.length})}</p></div><button class="icon-close" type="button" onclick="openQuoteSources()">×</button></div><div class="quote-sources-list"><div class="table-wrap"><table><thead><tr><th>${t('date')}</th><th>${t('product')}</th><th>${t('factory')}</th><th>${t('unitPrice')}</th><th>${t('moq')}</th><th>${t('note')}</th><th></th></tr></thead><tbody>${records.map(item=>`<tr><td>${fmtDay(item.quoted_at)}</td><td>${esc(item.product_name)}</td><td>${esc(item.factory_name)}</td><td>${quoteMoney(item)}</td><td>${esc(item.moq||'-')}</td><td>${esc(item.note||'-')}</td><td>${user.role==='brand'?`<button class="text-action" onclick="quoteSourcesModal.close();openQuoteEdit(${item.id})">${t('edit')}</button>`:''}</td></tr>`).join('')||`<tr><td colspan="7" class="empty">${t('noQuote')}</td></tr>`}</tbody></table></div></div><footer><button class="secondary" type="button" onclick="openQuoteSources()">${t('back')}</button><button class="primary" type="button" onclick="quoteSourcesModal.close()">${t('close')}</button></footer>`;};
const applyLanguage = () => { const nav={dashboard:['工作看板','Dashboard','작업 보드'],orders:['代工订单','OEM Orders','OEM 주문'],documents:['文档归档','Documents','문서 보관'],factories:['互联工厂','Factories','연결 공장'],quotes:['报价与成本','Quotes & Cost','견적 및 비용'],risks:['风险看板','Risks','리스크 보드']};const index={zh:0,en:1,ko:2}[language];document.querySelectorAll('.nav').forEach(button=>button.textContent=nav[button.dataset.view][index]);$('#language').value=language;$('#export').textContent=language==='zh'?'导出':language==='en'?'Export':'내보내기';$('#newOrder').textContent=language==='zh'?'+ 新建代工订单':language==='en'?'+ New OEM Order':'+ OEM 주문 생성';};
const milestoneDocumentTypes = {
  formula_confirmed: ['finished_formula'], packaging_confirmed: ['label'], contract_confirmed: ['brand_contract', 'factory_contract', 'contract_file'], raw_material_purchase: ['raw_material_coa'], raw_material_received: ['raw_material_coa'], finished_production: ['finished_product_coa'], semi_finished_test: ['finished_product_coa'], shipment: ['certificate_of_origin', 'free_sale_certificate', 'health_certificate']
};
let openedOrderDetail = null;
const relevantFiles = milestone => (openedOrderDetail?.files || []).filter(file => (milestoneDocumentTypes[milestone.node_key] || []).includes(file.document_type));
window.remindOrder = async (orderId, context = '') => {
  const order = openedOrderDetail?.id === Number(orderId) ? openedOrderDetail : orderById(orderId);
  try {
    const contacts = await api(`/api/orders/${orderId}/contacts`);
    $('#reminderForm').innerHTML = `<div class="modal-head"><div><h2>提醒对方</h2><p>${esc(context || '订单协作')} · 选择已注册成员的工作邮箱并留下系统记录。</p></div><button type="button" class="icon-close" onclick="reminderModal.close()">×</button></div><div class="form-grid"><label class="wide">收件人${contacts.length ? `<span class="contact-list">${contacts.map(contact => `<label><input type="checkbox" name="contact" value="${esc(contact.email)}" data-name="${esc(contact.name)}" checked>${esc(contact.name)} <small>${esc(contact.email)}</small></label>`).join('')}</span>` : '<small>暂无已注册的可通知联系人；仍可保留系统内提醒。</small>'}</label><label class="wide">提醒内容<textarea name="message" required>请更新当前进度、待提交资料或需要确认的事项。</textarea></label></div><footer><button type="button" class="secondary" onclick="reminderModal.close()">取消</button><button class="outline" type="button" id="saveReminder">仅发送系统提醒</button><button class="primary">发送提醒并发送邮件</button></footer>`;
    const submit = async sendEmail => { const form = $('#reminderForm'); const message = new FormData(form).get('message').trim(); if (!message) return; try { const selected = [...form.querySelectorAll('input[name="contact"]:checked')].map(item => item.value); const result = await api(`/api/orders/${orderId}/reminders`, { method:'POST', body:JSON.stringify({ message, context, recipients: sendEmail ? selected : [] }) }); if (sendEmail && selected.length && !result.email?.sent) { const subject = `NutriLink 提醒：${order?.product_name || '订单'}${context ? ` - ${context}` : ''}`; const body = `${message}\n\n订单：${order?.product_name || '-'}\n工厂：${order?.factory_name || '-'}\n\n请登录系统查看详情：${location.origin}`; window.location.href = `mailto:${selected.map(email => encodeURIComponent(email)).join(',')}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`; } reminderModal.close(); await loadData(); openDetail(orderId); } catch (error) { alert(error.message); } };
    $('#reminderForm').onsubmit = event => { event.preventDefault(); submit(true); }; $('#saveReminder').onclick = () => submit(false); $('#reminderModal').showModal();
  } catch (error) { alert(error.message); }
};
window.openProductInfoForm = id => { const order = openedOrderDetail?.id === Number(id) ? openedOrderDetail : orderById(id); $('#orderForm').innerHTML = `<div class="modal-head"><div><h2>产品与配方信息</h2><p>保存后系统会记录变更字段、原值、新值和修改人。</p></div><button type="button" class="icon-close" onclick="orderModal.close()">×</button></div><div class="form-grid"><label>配方版本<input name="formula_version" value="${esc(order.formula_version || '')}"></label><label>包装规格<input name="pack_spec" value="${esc(order.pack_spec || '')}"></label><label>保质期要求（月）<input type="number" min="1" name="shelf_life" value="${esc(order.shelf_life || '')}"></label><label class="wide">完整配方<textarea name="formula">${esc(order.formula || '')}</textarea></label></div><footer><button type="button" class="secondary" onclick="orderModal.close()">取消</button><button class="primary">保存修改</button></footer>`; $('#orderModal').showModal(); $('#orderForm').onsubmit = async event => { event.preventDefault(); try { await api(`/api/orders/${id}/product-info`, { method:'PATCH', body:JSON.stringify(Object.fromEntries(new FormData(event.target))) }); $('#orderModal').close(); await loadData(); openDetail(id); } catch (error) { alert(error.message); } }; };
window.showMilestoneDetail = (orderId, milestoneId) => { const order = openedOrderDetail?.id === Number(orderId) ? openedOrderDetail : null; const milestone = order?.milestones?.find(item => item.id === Number(milestoneId)); if (!order || !milestone) return; const filesForNode = relevantFiles(milestone); const actionsForNode = (order.actions || []).filter(item => String(item.action || '').includes(`：${milestone.node_name}`) || filesForNode.some(file => file.id === item.file_id)); $('#milestoneModalBody').innerHTML = `<div class="modal-head"><div><h2>${esc(milestone.node_name)}</h2><p>${milestone.status || '待开始'} · 计划 ${fmtDay(milestone.plan_date)}${milestone.actual_date ? ` · 实际 ${fmtDay(milestone.actual_date)}` : ''}</p></div><button class="icon-close" onclick="milestoneModal.close()">×</button></div><div class="milestone-modal-content"><section><div class="section-label">关联文件</div>${filesForNode.map(file => `<div class="audit-item"><b>${esc(file.original_name)}</b>${previewButton(file.id)}<small>${esc(docTypes[file.document_type] || file.document_type)} · ${esc(file.uploaded_by_name || '系统')} · ${fmtDate(file.created_at)}</small></div>`).join('') || '<p class="empty">此节点暂无按文件类型匹配的文件。</p>'}</section><section><div class="section-label">操作记录</div>${actionsForNode.map(item => `<div class="audit-item"><b>${esc(item.action)}</b><span>${esc(item.detail || '操作更新')}</span><small>${esc(item.actor_name)} · ${fmtDate(item.created_at)}</small></div>`).join('') || '<p class="empty">此节点暂无已提交或确认的操作记录。</p>'}</section></div><footer><button class="outline" type="button" onclick="milestoneModal.close();remindOrder(${order.id},'${esc(milestone.node_name)}')">提醒</button><button class="primary" type="button" onclick="completeMilestone(${order.id},${milestone.id})">完成</button></footer>`; $('#milestoneModal').showModal(); };
window.completeMilestone = async (orderId, milestoneId) => { try { await api(`/api/orders/${orderId}/milestones/${milestoneId}`, { method: 'PUT', body: JSON.stringify({ finalize: true }) }); $('#milestoneModal').close(); await loadData(); openDetail(orderId); } catch (error) { alert(error.message); } };
window.openDetail = async (id, focus = '') => {
  const order = await api(`/api/orders/${id}`); openedOrderDetail = order;
  const statusClass = milestone => milestone.actual_date || milestone.status === '已完成' ? 'complete' : overdue(milestone) || milestone.status === '延期' ? 'late' : milestone.status === '进行中' ? 'current' : 'pending';
  const milestoneRowsHtml = (order.milestones || []).map(item => `<tr class="milestone-${statusClass(item)}"><td><b>${esc(item.node_name)}</b><small>${item.status || '待开始'}</small></td><td><input class="date-input" type="date" value="${esc(item.plan_date || '')}" ${user.role === 'factory' ? 'disabled' : ''} onchange="updateMilestone(${order.id},${item.id},'plan_date',this.value)"></td><td><input class="date-input" type="date" value="${esc(item.actual_date || '')}" onchange="updateMilestone(${order.id},${item.id},'actual_date',this.value)"></td><td><select onchange="updateMilestone(${order.id},${item.id},'status',this.value)">${['待开始','进行中','已完成','延期'].map(value => `<option ${item.status === value ? 'selected' : ''}>${value}</option>`).join('')}</select></td><td><input class="reason-input" value="${esc(item.delay_reason || '')}" placeholder="延期时填写原因" onchange="updateMilestone(${order.id},${item.id},'delay_reason',this.value)"></td><td><button class="text-action" onclick="showMilestoneDetail(${order.id},${item.id})">详情</button><button class="text-action" onclick="remindOrder(${order.id},'${esc(item.node_name)}')">提醒</button></td></tr>`).join('');
  const timelineHtml = (order.milestones || []).map(item => `<li class="${statusClass(item)}"><i>${item.sequence}</i><div><b>${esc(item.node_name)}</b><small>${item.status || '待开始'} · 计划 ${fmtDay(item.plan_date)}${item.actual_date ? ` · 实际 ${fmtDay(item.actual_date)}` : ''}${item.delay_reason ? ` · ${esc(item.delay_reason)}` : ''}</small></div><button class="text-action" onclick="showMilestoneDetail(${order.id},${item.id})">详情</button></li>`).join('');
  const fileRows = (order.files || []).map(file => `<tr><td><span class="document-name"><b>${esc(file.original_name)}</b>${previewButton(file.id)}</span></td><td>${esc(docTypes[file.document_type] || file.document_type || '其他文件')}</td><td>${esc(file.uploaded_by_name || '系统')}</td><td>${esc(order.factory_name || '-')}</td><td>${fmtDate(file.created_at)}</td><td>${badge(file.review_status)}</td><td><button class="text-action" onclick="downloadFile(${file.id},'${esc(file.original_name)}')">下载</button>${reviewActions(file,order.id)}${user.role === 'brand' || file.uploaded_by_name === user.name ? `<button class="text-action danger" onclick="deleteFile(${file.id},${order.id})">删除</button>` : ''}</td></tr>`).join('') || '<tr><td colspan="7" class="empty">尚未上传文件。</td></tr>';
  const comments = order.comments || [];
  const commentRows = comments.map(item => `<li><b>${esc(item.created_by_name)}</b><span>${esc(item.message)}</span>${item.mentions ? `<small>提及：${esc(item.mentions)}</small>` : ''}<small>${fmtDate(item.created_at)}</small></li>`).join('') || '<li class="empty">暂无留言记录。</li>';
  $('#detailBody').innerHTML = `<div id="detailTop" class="modal-head"><div><h2>${esc(order.product_name)}</h2><p>${esc(order.factory_name)}${order.sku ? ` · SKU ${esc(order.sku)}` : ''}</p></div><button class="icon-close" onclick="detailModal.close()">×</button></div><div class="detail-summary"><div><small>当前节点</small><b>${esc(order.node || '待确认')}</b>${progress(order)}</div><div><small>约定交期</small><b>${fmtDay(order.due_date)}</b></div><div><small>保质期要求</small><b>${order.shelf_life ? `${esc(order.shelf_life)} 个月` : '待确认'}</b></div><div><small>待反馈提醒</small><b>${(reminders || []).filter(item => item.order_id === order.id && !item.read_at).length} 条</b></div></div><div class="detail-columns"><section class="panel inset"><div class="panel-head"><div><h3>产品与配方信息</h3><p>品牌上传初版后，工厂可提交修改，系统记录差异。</p></div><span><button class="text-action" onclick="openProductInfoForm(${order.id})">${user.role === 'factory' ? '提交修改' : '编辑'}</button><button class="text-action" onclick="remindOrder(${order.id},'产品与配方信息')">提醒</button></span></div><dl class="facts">${[['产品名称',order.product_name],['工厂名称',order.factory_name],['SKU / 条码',order.sku || '确认配方和工厂后申请'],['合同号',order.contract_no || '合同待上传'],['生产数量',order.quantity],['配方版本',order.formula_version],['包装规格',order.pack_spec],['订单状态',order.status]].map(([label,value]) => `<div><dt>${label}</dt><dd>${esc(value || '待补充')}</dd></div>`).join('')}</dl><div class="formula"><small>完整配方</small><p>${esc(order.formula || '待补充')}</p></div></section><section class="panel inset"><div class="panel-head"><h3>里程碑状态</h3><small>深色为进行中，浅色为待开始</small></div><ol class="timeline milestone-timeline">${timelineHtml}</ol></section></div><section id="milestoneSection" class="panel inset milestone-board"><div class="panel-head"><div><h3>里程碑计划与预警</h3><p>计划日期由品牌方维护；实际日期、状态和延期原因双方可更新。</p></div><button class="text-action" onclick="remindOrder(${order.id},'里程碑计划')">提醒</button></div><div class="table-wrap"><table><thead><tr><th>节点</th><th>计划日期</th><th>实际日期</th><th>状态</th><th>延期原因</th><th>操作</th></tr></thead><tbody>${milestoneRowsHtml}</tbody></table></div></section><section id="documentsSection" class="panel inset documents document-table"><div class="panel-head"><div><h3>订单全部文档</h3><p>选择文件类型后上传；工厂文件需经过审批。</p></div><form id="uploadForm"><select name="document_type" required><option value="" selected disabled>请选择文件类型</option>${Object.entries(docTypes).map(([value,label]) => `<option value="${value}">${label}</option>`).join('')}<option value="custom">+ 手动添加新选项</option></select><input name="custom_document_type" hidden placeholder="自定义文件类型"><input type="file" name="file" required><button class="outline">上传文件</button><button type="button" class="outline" onclick="downloadAllFiles(${order.id})">下载全部</button><button type="button" class="text-action" onclick="remindOrder(${order.id},'订单文件')">提醒</button></form></div><div class="table-wrap"><table><thead><tr><th>文件名称</th><th>文件类型</th><th>上传人</th><th>所属工厂</th><th>上传时间</th><th>审批状态</th><th></th></tr></thead><tbody>${fileRows}</tbody></table></div></section><section id="commentsSection" class="panel inset comments"><div class="comment-heading"><h3>留言</h3><button class="text-action" onclick="remindOrder(${order.id},'留言')">提醒</button></div><form id="commentForm" class="comment-form"><textarea name="message" required placeholder="填写留言或确认结论"></textarea><input name="mentions" placeholder="@成员或部门（选填）"><button class="primary">发送留言</button></form><details class="message-history"><summary>查看全部 ${comments.length} 条留言记录</summary><ol>${commentRows}</ol></details></section>`;
  $('#detailModal').showModal(); if (focus) requestAnimationFrame(() => $(`#${focus}`)?.scrollIntoView({ behavior:'smooth', block:'start' })); const commentHistory = $('#commentsSection .message-history'); commentHistory.ontoggle = () => { commentHistory.querySelector('summary').textContent = commentHistory.open ? '收起留言记录' : `查看全部 ${comments.length} 条留言记录`; }; const type = $('#uploadForm select'), custom = $('#uploadForm input[name="custom_document_type"]'); type.onchange = () => { custom.hidden = type.value !== 'custom'; custom.required = type.value === 'custom'; }; $('#uploadForm').onsubmit = async event => { event.preventDefault(); const form = new FormData(event.target); if (form.get('document_type') === 'custom') form.set('document_type', form.get('custom_document_type')); try { await api(`/api/orders/${order.id}/files`, { method:'POST', body:form }); await loadData(); openDetail(order.id); } catch (error) { alert(error.message); } }; $('#commentForm').onsubmit = async event => { event.preventDefault(); try { await api(`/api/orders/${order.id}/comments`, { method:'POST', body:JSON.stringify(Object.fromEntries(new FormData(event.target))) }); await loadData(); openDetail(order.id); } catch (error) { alert(error.message); } };
};
window.downloadAllFiles=async orderId=>{const order=await api(`/api/orders/${orderId}`);for(const file of order.files)await downloadFile(file.id,file.original_name);};
async function getFile(idOrUrl){const url=String(idOrUrl).startsWith('/')?idOrUrl:`/api/files/${idOrUrl}`;const res=await fetch(url,{headers:{Authorization:`Bearer ${localStorage.token}`}});if(!res.ok){const body=await res.json().catch(()=>({}));throw new Error(body.error||'文件读取失败');}return res.blob();}
const previewHome=document.body;const clearFilePreview=()=>{$('#filePreviewFrame').removeAttribute('src');$('#filePreviewFrame').removeAttribute('srcdoc');if(previewUrl)URL.revokeObjectURL(previewUrl);previewUrl=null;};
window.closeFilePreview=()=>{const modal=$('#filePreviewModal');clearFilePreview();modal.hidden=true;if(modal.parentElement!==previewHome)previewHome.append(modal);};
window.previewFile=async id=>{try{clearFilePreview();const modal=$('#filePreviewModal');if($('#milestoneModal').open)$('#milestoneModal').append(modal);else if($('#detailModal').open)$('#detailModal').append(modal);$('#filePreviewMeta').textContent='正在加载文件';modal.hidden=false;const file=await getFile(id);previewUrl=URL.createObjectURL(file);const frame=$('#filePreviewFrame');if(file.type.startsWith('image/'))frame.srcdoc=`<style>html,body{margin:0;height:100%;display:grid;place-items:center;background:#f2f4f3}img{max-width:100%;max-height:100%;object-fit:contain}</style><img src="${previewUrl}" alt="文件预览">`;else{frame.removeAttribute('srcdoc');frame.src=previewUrl;}}catch(error){closeFilePreview();alert(error.message);}};
$('#filePreviewFrame').addEventListener('load',()=>{if(!$('#filePreviewModal').hidden)$('#filePreviewMeta').textContent='文件已加载，可关闭后返回订单详情';});document.addEventListener('keydown',event=>{if(event.key==='Escape')closeFilePreview();});$('#detailModal').addEventListener('close',closeFilePreview);$('#milestoneModal').addEventListener('close',closeFilePreview);
window.downloadFile=async(id,name)=>{try{const link=document.createElement('a');link.href=URL.createObjectURL(await getFile(id));link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);}catch(error){alert(error.message);}};window.deleteFile=async(id,orderId)=>{if(!confirm('确认删除这个文件？'))return;try{await api(`/api/files/${id}`,{method:'DELETE'});await loadData();openDetail(orderId);}catch(error){alert(error.message);}};
$('#export').onclick=()=>{const source=view==='quotes'?quotes.map(item=>[item.product_name,item.factory_name,item.quoted_at,item.currency,item.unit_price,item.moq,item.sample_fee,item.production_days,item.payment_terms]):orders.map(item=>[item.product_name,item.factory_name,item.sku,item.node,item.progress,item.due_date,item.status]);const header=view==='quotes'?['产品','工厂','报价日期','币种','单价','MOQ','打样费','生产周期','付款条件']:['产品','工厂','SKU','当前节点','进度','交期','状态'];const csv=[header,...source].map(row=>row.map(value=>`"${String(value??'').replaceAll('"','""')}"`).join(',')).join('\n');const link=document.createElement('a');link.href=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));link.download=`NutriLink_${view}.csv`;link.click();};
document.querySelectorAll('.nav').forEach(button=>button.onclick=()=>showView(button.dataset.view));$('#newOrder').onclick=openOrderForm;$('#logout').onclick=()=>{closeFilePreview();localStorage.removeItem('token');location.reload();};
async function signIn(register){const data=Object.fromEntries(new FormData($('#authForm')));try{const result=await api(register?'/api/auth/register':'/api/auth/login',{method:'POST',body:JSON.stringify(data)});localStorage.token=result.token;await start(result.user);}catch(error){$('#authError').textContent=error.message;}}async function start(currentUser){user=currentUser;$('#auth').hidden=true;$('#app').hidden=false;$('#who').textContent=user.name;$('#role').textContent=user.role==='factory'?'Factory Workspace':'Brand PMO';applyLanguage();await loadData();render();}$('#authForm').onsubmit=event=>{event.preventDefault();signIn(false);};$('#register').onclick=()=>signIn(true);$('#language').onchange=event=>{language=event.target.value;localStorage.setItem('nutrilink-language',language);applyLanguage();render();};(async()=>{closeFilePreview();if(!localStorage.token)return;try{await start((await api('/api/auth/me')).user);}catch{localStorage.removeItem('token');}})();
